import{c as t,Q as a,j as s,m as r}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"First-Run Wizard","description":"Get your Phlix server running in minutes with the first-run setup wizard.","frontmatter":{"title":"First-Run Wizard","description":"Get your Phlix server running in minutes with the first-run setup wizard."},"headers":[],"relativePath":"first-run.md","filePath":"first-run.md"}'),o={name:"first-run.md"};function i(n,e,l,c,h,d){return a(),s("div",null,[...e[0]||(e[0]=[r(`<p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.6 <strong>Since:</strong> 0.18.0</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>The first-run wizard starts automatically when you boot Phlix with no admin account configured. It walks you through creating your admin login, adding media library folders, choosing library types, setting language/timezone preferences, and enabling DLNA discovery — taking about five minutes from server boot to a ready-to-scan library.</p><h2 id="screenshots-flow-description" tabindex="-1">Screenshots / Flow Description <a class="header-anchor" href="#screenshots-flow-description" aria-label="Permalink to &quot;Screenshots / Flow Description&quot;">​</a></h2><p>The wizard runs in your browser and presents each step one at a time. Work through each screen in order.</p><h3 id="step-1-—-welcome-screen" tabindex="-1">Step 1 — Welcome Screen <a class="header-anchor" href="#step-1-—-welcome-screen" aria-label="Permalink to &quot;Step 1 — Welcome Screen&quot;">​</a></h3><p>When you first access your server, the wizard displays a welcome screen. Open your browser and navigate to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:32400/web</span></span></code></pre></div><p>Or, if accessing from another machine on your network, replace <code>localhost</code> with your server&#39;s LAN IP address (e.g., <code>http://192.168.1.100:32400/web</code>).</p><p>Click <strong>Get Started</strong> to begin.</p><h3 id="step-2-—-admin-account-creation" tabindex="-1">Step 2 — Admin Account Creation <a class="header-anchor" href="#step-2-—-admin-account-creation" aria-label="Permalink to &quot;Step 2 — Admin Account Creation&quot;">​</a></h3><p>Create your server administrator account. This account has full access to all server settings, library management, and user management.</p><ul><li><strong>Email</strong> — Enter a valid email address. This is your login username.</li><li><strong>Password</strong> — Choose a strong password. An on-screen strength meter will update as you type.</li><li><strong>Confirm Password</strong> — Re-enter your password to confirm there are no typos.</li></ul><p>Click <strong>Create Account</strong> when the strength meter shows a strong rating. You can update the email and password later in <strong>Settings → Account</strong>.</p><h3 id="step-3-—-library-path-configuration" tabindex="-1">Step 3 — Library Path Configuration <a class="header-anchor" href="#step-3-—-library-path-configuration" aria-label="Permalink to &quot;Step 3 — Library Path Configuration&quot;">​</a></h3><p>Tell Phlix where your media files live. Click <strong>Add Folder</strong> and browse to each directory you want to include.</p><p>Common examples:</p><table tabindex="0"><thead><tr><th>Content type</th><th>Example path</th></tr></thead><tbody><tr><td>Movies</td><td><code>/media/movies</code></td></tr><tr><td>TV shows</td><td><code>/media/tv</code></td></tr><tr><td>Music</td><td><code>/media/music</code></td></tr><tr><td>Photos</td><td><code>/media/photos</code></td></tr><tr><td>Books</td><td><code>/media/books</code></td></tr><tr><td>Audiobooks</td><td><code>/media/audiobooks</code></td></tr></tbody></table><p>You can add multiple folders for the same library type (for example, <code>/data/movies</code> and <code>/backup/movies</code>). Folders that don&#39;t exist or are inaccessible will be flagged — correct the path or remove the entry before proceeding.</p><p>Click <strong>Continue</strong> when all desired folders are listed.</p><h3 id="step-4-—-library-type-selection" tabindex="-1">Step 4 — Library Type Selection <a class="header-anchor" href="#step-4-—-library-type-selection" aria-label="Permalink to &quot;Step 4 — Library Type Selection&quot;">​</a></h3><p>For each folder you added, choose what kind of content it contains:</p><ul><li><strong>Movies</strong> — Individual film files</li><li><strong>TV Shows</strong> — Episodic content organized in folders or by season</li><li><strong>Music</strong> — Albums, artists, and tracks</li><li><strong>Photos</strong> — Image collections</li><li><strong>Books</strong> — E-books and PDFs</li><li><strong>Audiobooks</strong> — Audio book files</li></ul><p>You can create multiple libraries (for example, one Movies library and one TV Shows library) or put everything in a single library. The type helps Phlix fetch the correct metadata and display posters, descriptions, and episode guides.</p><p>Click <strong>Continue</strong> when each folder has a type assigned.</p><h3 id="step-5-—-library-scan-trigger" tabindex="-1">Step 5 — Library Scan Trigger <a class="header-anchor" href="#step-5-—-library-scan-trigger" aria-label="Permalink to &quot;Step 5 — Library Scan Trigger&quot;">​</a></h3><p>Choose when Phlix should scan your libraries for media files:</p><ul><li><strong>Scan Now</strong> — Triggers an immediate background scan. Large libraries may take several minutes. You can continue using the wizard while the scan runs.</li><li><strong>Scan Later</strong> — Defers the scan to a scheduled time. You can trigger it manually from <strong>Settings → Libraries</strong> whenever you are ready.</li></ul><p>You can always change the scan schedule later in <strong>Settings → Libraries → Scan Schedule</strong>.</p><p>Click <strong>Continue</strong>.</p><h3 id="step-6-—-hub-connection" tabindex="-1">Step 6 — Hub Connection <a class="header-anchor" href="#step-6-—-hub-connection" aria-label="Permalink to &quot;Step 6 — Hub Connection&quot;">​</a></h3><p>Connect this server to a Phlix Hub for remote access and multi-server management. This step is optional.</p><ul><li><strong>Connect Now</strong> — Enter your hub URL (e.g., <code>https://hub.phlix.example.com</code>) and authenticate with your hub credentials. See <a href="./hub/claim-server.html">Hub Claim Guide</a> for the full claim flow.</li><li><strong>Skip</strong> — Defer hub connection. You can set up hub access later from <strong>Settings → Hub</strong>.</li></ul><p>Even when skipped, you can connect clients directly to the server over your LAN or configure your own remote access (reverse proxy, Tailscale VPN, etc.).</p><p>Click <strong>Continue</strong>.</p><h3 id="step-7-—-language-and-timezone" tabindex="-1">Step 7 — Language and Timezone <a class="header-anchor" href="#step-7-—-language-and-timezone" aria-label="Permalink to &quot;Step 7 — Language and Timezone&quot;">​</a></h3><p>Set defaults for the server&#39;s display language and local time representation:</p><ul><li><strong>Language</strong> — Select your preferred language from the dropdown.</li><li><strong>Timezone</strong> — Select your city or region to ensure correcttimestamps on recording schedules, watch history, and DLNA announcements.</li></ul><p>These settings affect the web portal, API responses, and any scheduled tasks. They can be changed at any time in <strong>Settings → General</strong>.</p><p>Click <strong>Continue</strong>.</p><h3 id="step-8-—-dlna-server-toggle" tabindex="-1">Step 8 — DLNA Server Toggle <a class="header-anchor" href="#step-8-—-dlna-server-toggle" aria-label="Permalink to &quot;Step 8 — DLNA Server Toggle&quot;">​</a></h3><p>DLNA (Digital Living Network Alliance) enables other devices on your network — smart TVs, game consoles, media players — to discover and stream from your Phlix server without needing a dedicated client app.</p><ul><li><strong>Enable DLNA</strong> — Allows device discovery on your local network. Phlix will announce itself to any DLNA-compatible device.</li><li><strong>Disable DLNA</strong> — Turns off network discovery. You can still access content through dedicated client apps.</li></ul><p>If you enable DLNA, the server will listen on port 1900 (UDP) for SSDP discovery requests and serve content over HTTP on the same port as the web portal.</p><p>Click <strong>Continue</strong>.</p><h3 id="step-9-—-web-dashboard-ready" tabindex="-1">Step 9 — Web Dashboard Ready <a class="header-anchor" href="#step-9-—-web-dashboard-ready" aria-label="Permalink to &quot;Step 9 — Web Dashboard Ready&quot;">​</a></h3><p>The wizard is complete. You land on the Phlix web dashboard, which shows:</p><ul><li>Your configured libraries on the home screen</li><li>Ongoing library scans in the top-right notification area</li><li>The navigation sidebar for browsing content, managing libraries, and adjusting settings</li></ul><p>Your server is now ready to stream to clients. Download a client app for your device from the <a href="./clients/overview.html">Clients overview</a>.</p><h2 id="shell-blocks" tabindex="-1">Shell Blocks <a class="header-anchor" href="#shell-blocks" aria-label="Permalink to &quot;Shell Blocks&quot;">​</a></h2><p>These commands are useful for operators managing a headless server.</p><p><strong>Verify the server is running:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:32400/api/v1/system/status</span></span></code></pre></div><p>Expected response includes <code>&quot;status&quot;: &quot;ok&quot;</code> and the server version.</p><p><strong>Check library paths on disk:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /media/movies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /media/tv</span></span></code></pre></div><p><strong>Trigger a manual library rescan via CLI:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public/index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> library:scan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p><strong>View DLNA server status:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:32400/api/v1/system/dlna</span></span></code></pre></div><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="admin-account-email-already-in-use" tabindex="-1">Admin account email already in use <a class="header-anchor" href="#admin-account-email-already-in-use" aria-label="Permalink to &quot;Admin account email already in use&quot;">​</a></h3><p><strong>Symptom:</strong> The wizard refuses to create the account and shows &quot;An account with this email already exists.&quot;</p><p><strong>Fix:</strong> An admin account was already created on this server (possibly during a previous run that did not complete). If you know the existing credentials, log in with them and change the password from <strong>Settings → Account</strong>. If you have lost access, use the account recovery flow from the login screen. If the server has no other admin, you can reset the database and run the wizard again — but this erases all libraries, watch history, and user accounts.</p><h3 id="library-paths-not-accessible" tabindex="-1">Library paths not accessible <a class="header-anchor" href="#library-paths-not-accessible" aria-label="Permalink to &quot;Library paths not accessible&quot;">​</a></h3><p><strong>Symptom:</strong> A folder shows a warning icon in step 3, or the scan completes with files missing or a &quot;path not found&quot; error.</p><p><strong>Fix:</strong> Verify the folder exists on the server&#39;s filesystem: <code>ls /media/movies</code>. If the folder exists but is owned by root, either change ownership (<code>sudo chown -R phlix:phlix /media/movies</code>) or grant read access to the phlix process user. If the path is a network mount (NFS, SMB), confirm the mount is still active and the phlix process has network access to the mount server. Correct the path in <strong>Settings → Libraries</strong> after the wizard completes.</p><h3 id="initial-scan-hangs-or-times-out" tabindex="-1">Initial scan hangs or times out <a class="header-anchor" href="#initial-scan-hangs-or-times-out" aria-label="Permalink to &quot;Initial scan hangs or times out&quot;">​</a></h3><p><strong>Symptom:</strong> The scan progress indicator appears stuck, or the wizard shows a timeout error after several minutes for a large library.</p><p><strong>Fix:</strong> Very large libraries (tens of thousands of files) or slow network mounts can exceed the default timeout. From <strong>Settings → Libraries</strong>, defer the scan and trigger it manually at a convenient time: set <strong>Scan Schedule</strong> to a manual-only setting, then click <strong>Scan Now</strong> when the server is lightly loaded. If using network storage, ensure the connection is stable and the mount uses a protocol with decent read performance (SMBv3 or NFSv4 rather than SMBv1).</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./libraries/overview.html">Libraries overview</a> — Add, remove, and manage your media libraries</li><li><a href="./clients/overview.html">Clients overview</a> — Connect playback apps on TV, mobile, and desktop</li><li><a href="./hub/remote-access.html">Hub remote access</a> — Set up secure remote access without opening ports</li><li><a href="./advanced/live-tv.html">Live TV</a> — Watch and record live television</li><li><a href="./reference/cli.html">CLI reference</a> — Server management commands</li></ul>`,72)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
